#[inline]
pub fn is_empty_nfkd(cp: u32) -> bool {
    EMPTY_RANGES.binary_search_by(|&(lo, hi)| {
        if cp < lo { core::cmp::Ordering::Greater }
        else if cp > hi { core::cmp::Ordering::Less }
        else { core::cmp::Ordering::Equal }
    }).is_ok()
}

#[inline]
pub fn lookup_map(cp: u32) -> Option<(u8, &'static [u8])> {
    match NFKD_MAP.binary_search_by_key(&cp, |e| e.cp) {
        Ok(i) => {
            let e = NFKD_MAP[i];
            let off = e.off as usize;
            Some((e.flags, &NFKD_POOL[off..off + e.len as usize]))
        }
        Err(_) => None,
    }
}
